namespace {thread_local std::map<std::filesystem::path,unsigned>personalDepth;}
PersonalDataLock::PersonalDataLock(const std::filesystem::path&p):root(std::filesystem::absolute(p).lexically_normal()){if(++personalDepth[root]>1)return;try{auto path=root/L"personal-data.lock";safePath(path);HANDLE file=CreateFileW(path.c_str(),GENERIC_READ|GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_ALWAYS,FILE_ATTRIBUTE_NORMAL|FILE_FLAG_OPEN_REPARSE_POINT,nullptr);require(file!=INVALID_HANDLE_VALUE,"personal lock file");OVERLAPPED at{};bool locked=false;for(unsigned i=0;i<200;++i){if(LockFileEx(file,LOCKFILE_EXCLUSIVE_LOCK|LOCKFILE_FAIL_IMMEDIATELY,0,MAXDWORD,MAXDWORD,&at)){locked=true;break;}if(GetLastError()!=ERROR_LOCK_VIOLATION)break;Sleep(10);}if(!locked){CloseHandle(file);throw JsonError("personal lock busy");}handle=file;}catch(...){personalDepth.erase(root);throw;}}
