std::filesystem::path userRoot(){PWSTR path=nullptr;require(SUCCEEDED(SHGetKnownFolderPath(FOLDERID_LocalAppData,0,nullptr,&path)),"user folder unavailable");std::filesystem::path p(path);CoTaskMemFree(path);p/=L"PrivateInput";safePath(p);std::filesystem::create_directories(p);return p;}
std::string protect(const std::string&s){require(s.size()<=8388608,"private plaintext limit");char label[]="PrivateInput/activity-local/v1";DATA_BLOB in{DWORD(s.size()),reinterpret_cast<BYTE*>(const_cast<char*>(s.data()))},entropy{sizeof(label),reinterpret_cast<BYTE*>(label)};Blob out;require(CryptProtectData(&in,L"Linghe private activity",&entropy,nullptr,nullptr,CRYPTPROTECT_UI_FORBIDDEN,&out.value),"DPAPI encryption");return base64(Data(out.value.pbData,out.value.pbData+out.value.cbData));}
std::string unprotect(const std::string&s){auto value=unbase64(s);char label[]="PrivateInput/activity-local/v1";DATA_BLOB in{DWORD(value.size()),value.data()},entropy{sizeof(label),reinterpret_cast<BYTE*>(label)};Blob out;require(CryptUnprotectData(&in,nullptr,&entropy,nullptr,nullptr,CRYPTPROTECT_UI_FORBIDDEN,&out.value),"DPAPI authentication");require(out.value.cbData<=8388608,"private plaintext limit");return std::string(reinterpret_cast<char*>(out.value.pbData),out.value.cbData);}
void savePrivate(const std::filesystem::path&file,const Json&j){safePath(file);auto data=protect(j.dump());auto temp=file;temp+=L"."+wide(uuidText(newId()))+L".tmp";HANDLE h=CreateFileW(temp.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL|FILE_FLAG_WRITE_THROUGH|FILE_FLAG_OPEN_REPARSE_POINT,nullptr);require(h!=INVALID_HANDLE_VALUE,"private state staging");DWORD n=0;bool ok=WriteFile(h,data.data(),DWORD(data.size()),&n,nullptr)&&n==data.size()&&FlushFileBuffers(h);CloseHandle(h);if(!ok||!MoveFileExW(temp.c_str(),file.c_str(),MOVEFILE_WRITE_THROUGH|MOVEFILE_REPLACE_EXISTING)){DeleteFileW(temp.c_str());throw JsonError("private state save");}}
