struct URL {std::wstring origin,host;INTERNET_PORT port=0;bool tls=true;};
static URL parseURL(const std::string&s){require(s.size()<=2048&&s.find_first_of("\r\n\t ")==std::string::npos,"invalid server URL");URL out;out.origin=wide(s);while(!out.origin.empty()&&out.origin.back()=='/')out.origin.pop_back();URL_COMPONENTS c{};c.dwStructSize=sizeof(c);c.dwHostNameLength=c.dwUrlPathLength=c.dwUserNameLength=c.dwPasswordLength=c.dwExtraInfoLength=DWORD(-1);require(WinHttpCrackUrl(out.origin.c_str(),DWORD(out.origin.size()),0,&c),"invalid server URL");out.host.assign(c.lpszHostName,c.dwHostNameLength);out.port=c.nPort;out.tls=c.nScheme==INTERNET_SCHEME_HTTPS;bool loopback=out.host==L"127.0.0.1"||out.host==L"localhost"||out.host==L"[::1]"||out.host==L"::1";require(out.tls||(loopback&&c.nScheme==INTERNET_SCHEME_HTTP),"HTTPS server required");require(c.dwUserNameLength==0&&c.dwPasswordLength==0&&c.dwUrlPathLength==0&&c.dwExtraInfoLength==0&&!out.host.empty(),"server must be HTTPS origin without userinfo/path/query");return out;}
