 require((!body&&path=="/clipboard-live/v1/status")||(body&&(path=="/clipboard-live/v1/batch"||path=="/clipboard-live/v1/revoke")),"invalid live HTTP path");auto u=parseURL(origin);auto payload=body?body->dump():std::string{};require(payload.size()<=180224,"live HTTP request bound");
